window.MONSTER_CHUNK_144 = [{"name":"Giant Snapping Turtle","cr":10,"xp":9600,"alignment":"N","size":"Gargantuan","type":"animal","subtypes":["aquatic"],"init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":4,"ac_flat_footed":20,"ac_mods":"-2 Dex, +16 natural, -4 size","hp":150,"hd":"12d8+96","hdvalue":12,"fort":15,"ref":6,"will":7,"speed":[{"type":"land","speed":10},{"type":"swim","speed":20}],"melee":"bite +16 (2d10+16/19-20 plus grab)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"swallow whole","details":"2d8+11 acid damage, AC 18, 15 hp"}],"strength":33,"dexterity":6,"constitution":25,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":9,"cmb":24,"cmb_special":"+4 vs. grapple","cmd":32,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":20},{"skill":"Swim","value":24}],"sq":[{"type":"amphibious"}],"environments":["any aquatic"],"organizations":["solitary","band (2-4)"],"treasure":"none","description_visual":"This is a turtle of massive proportions, its shell an impenetrable coat of armor, and its snapping jaws capable of dismembering its prey.","group":"Turtle","source":"Tome of Horrors Complete (3pp)","description":"Giant snapping turtles are very large and very aggressive versions of their smaller cousins. They are found in large lakes, rivers, and inland seas. The average giant snapping turtle is 40 ft. in diameter, but they can grow to a diameter of 75 ft.\n\nA giant snapping turtle lurks near the shore or on the bottom of a body of water, where it remains motionless and hidden in its shell. When prey passes near, it shoots its neck out and bites.","ecology":"","habitat_society":"","credit":"The Giant Snapping Turtle originally appeared in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission."},{"name":"Greater Negative Energy Elemental","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"outsider","subtypes":["elemental","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["negative energy (40 ft. radius)"],"ac":26,"ac_touch":18,"ac_flat_footed":16,"ac_mods":"+9 Dex, +1 dodge, +8 natural, -2 size","hp":123,"hd":"13d10+52","hdvalue":13,"fort":8,"ref":17,"will":8,"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 slams +21 (2d8+5 plus 2d8 negative energy plus energy drain)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"channel negative energy","details":"5/day, 7d6, DC 18"},{"type":"death throes","details":"40 ft. radius, DC 20, 6d8 negative energy damage"},{"type":"energy drain","details":"2 levels, DC 20"},{"type":"negative energy"}],"strength":20,"dexterity":29,"constitution":18,"intelligence":10,"wisdom":11,"charisma":11,"baseatk":13,"cmb":20,"cmd":40,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Extra Channel"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":25},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":16},{"skill":"Knowledge (religion)","value":16},{"skill":"Perception","value":16},{"skill":"Stealth","value":17}],"languages":["Negative Energy Fluctuation"],"environments":["any (Plane of Negative Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a shimmering and wavering sphere of translucent gray energy with small motes of light winking in and out of existence along its spherical form.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Su","details":"A negative energy elemental that is killed explodes in a flash of swirling negative energy that affects all within the area (the radius for its death throes ability is the same as the radius for its negative energy aura). Living creatures within the area take 1d8 points of negative energy damage per two HD of the elemental. Negative energy based creatures and undead gain hit points equal to the amount of damage the death throes would have otherwise dealt. (The rules for temporary hit points and doubling hit points as detailed under the elemental's negative energy apply here.) A successful Reflex DC (save DC same as the elemental's negative energy save DC) reduces the damage by half."},{"type":"Negative Energy","kind":"Ex","details":"A negative energy elemental infuses a target hit by its slam attack with negative energy. This deals extra damage to a living target (as listed in the statistics block) but heals undead (and other negative energy based creatures) by the same amount. Undead (and other negative energy based creatures) can be healed above their normal hit point total, gaining extra hit points as temporary hit points. These temporary hit points disappear 1 minute later. Creatures healed to twice their normal hit points (that is, a creature whose hit points are effectively doubled) must succeed on a Fortitude save or explode in a burst of negative energy. The save DC is Constitution-based. See the table below for each negative energy elemental's save DC. Negative energy (such as an inflict spell or negative energy channeling) can heal negative energy elementals."},{"type":"Negative Energy Aura","kind":"Su","details":"A negative energy elemental radiates an aura of pure negative energy around it. Within a negative energy elemental's aura, class abilities that use negative energy, such as negative energy channeling or the Command Undead feat, function as if the user were 2 levels higher. Additionally, spells and spell-like abilities that use negative energy are maximized (as if the Maximize Spell metamagic feat had been used on them, but the spells don't require higher-level slots). Spells and spell-like abilities that are already maximized are unaffected by this benefit. This aura doesn't affect the negative energy channeling ability of the negative energy elemental using it, and its effects don't stack with those of other negative energy elementals. Within a negative energy elemental's aura, class abilities that use positive energy, such as positive energy channeling or the Turn Undead feat, function as if the user were 2 levels lower. Spells and spell-like abilities that use positive energy, including cure spells, require the caster to succeed on a Concentration check (DC 15 + the level of the spell). If the check fails, the spell doesn't function but is still lost as a prepared spell or spell slot. If the check succeeds, the spell functions normally."},{"type":"Negative Energy Channeling","kind":"Su","details":"A Large or larger negative energy elemental can channel negative energy as a cleric whose level equals the elemental's Hit Dice. The Will save DC includes a +2 racial bonus."}],"description":"Negative energy elementals are creatures of pure negative energy. They are found primarily on the Negative Energy Plane, but on rare occasions, one slips through a portal or is summoned to the Material Plane. These creatures seem to be able to communicate with others of their kind by changing the intensity of energy in their bodies and altering their shape ever so slightly. They don't speak any known languages. Negative energy elementals hate positive energy elementals and always attack them on sight. Aside from that, negative energy elementals rarely engage in combat. If confronted however and forced into battle, the creature responds by pummeling its foes with its powerful fists dealing negative energy to its foe.","ecology":"","habitat_society":""},{"name":"Greater Positive Energy Elemental","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"outsider","subtypes":["elemental","extraplanar"],"init":13,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["positive energy (40 ft. radius)"],"ac":26,"ac_touch":18,"ac_flat_footed":16,"ac_mods":"+9 Dex, +1 dodge, +8 natural, -2 size","hp":123,"hd":"13d10+52","hdvalue":13,"fort":8,"ref":17,"will":8,"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 slams +21 (2d8+5 plus 2d8 positive energy)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"blinding flash","details":"DC 20"},{"type":"channel positive energy","details":"5/day, 7d6, DC 18"},{"type":"death throes","details":"40 ft. radius, DC 20, 6d8 positive energy damage"},{"type":"positive energy"}],"strength":20,"dexterity":29,"constitution":18,"intelligence":10,"wisdom":11,"charisma":11,"baseatk":13,"cmb":20,"cmd":40,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Extra Channel"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse","type":"bonus"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Fly","value":25},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":16},{"skill":"Knowledge (religion)","value":16},{"skill":"Perception","value":16},{"skill":"Stealth","value":17}],"languages":["Positive Energy Manipulation"],"environments":["any (Plane of Positive Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature appears as a shimmering and wavering sphere of brilliant white energy with small motes of light winking in and out of existence along its spherical form.","group":"Elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Blinding Flash","kind":"Su","details":"Once every 1d4 rounds, a positive energy elemental of at least Medium size can release a burst of pure energy in a 10-foot radius. Creatures viewing this burst must succeed on a Fortitude save or be blinded for 1d10 rounds. See the table below for the save DC for each positive energy elemental's blinding flash. The save DC is Constitution-based."},{"type":"Death Throes","kind":"Su","details":"A positive energy elemental that is killed explodes in a flash of blinding positive energy that affects all within the area (the radius for its death throes ability is the same as the radius for its positive energy aura). Undead and negative energy based creatures within the area take 1d8 points of positive energy damage per two HD of the elemental. Positive energy based creatures (including creatures from the Material Plane) gain hit points equal to the amount of damage the death throes would have otherwise dealt. (The rules for temporary hit points and doubling hit points as detailed under the elemental's positive energy apply here.) A successful Reflex DC (save DC same as the elemental's positive energy save DC) reduces the damage by half. All creatures in the area must succeed on a Fortitude save (same DC as the elemental's positive energy save DC) or be blinded for 1d10 rounds. The save DC is Constitution-based."},{"type":"Positive Energy","kind":"Ex","details":"A positive energy elemental infuses a target hit by its slam attack with positive energy. This deals extra damage to an undead or negative energy based target (as listed in the statistics block) but heals positive energy based creatures (including creatures from the Material Plane) by the same amount. Such creatures can be healed above their normal hit point total, gaining extra hit points as temporary hit points. These temporary hit points disappear 1 minute later. Creatures healed to twice their normal hit points (that is, a creature whose hit points are effectively doubled) must succeed on a Fortitude save or explode in a burst of positive energy. The save DC is Constitution-based. See the table below for each positive energy elemental's save DC. Positive energy (such as a cure spell or positive energy channeling) can heal positive energy elementals."},{"type":"Positive Energy Aura","kind":"Su","details":"A positive energy elemental radiates an aura of pure positive energy around it. Within a positive energy elemental's aura, class abilities that use positive energy, such as positive energy channeling or the Turn Undead feat, function as if the user were 2 levels higher. Additionally, spells and spell-like abilities that use positive energy are maximized (as if the Maximize Spell metamagic feat had been used on them, but the spells don't require higher-level slots). Spells and spell-like abilities that are already maximized are unaffected by this benefit. This aura doesn't affect the positive energy channeling ability of the positive energy elemental using it, and its effects don't stack with those of other positive energy elementals. Within a positive energy elemental's aura, class abilities that use negative energy, such as negative energy channeling or the Command Undead feat, function as if the user were 2 levels lower. Spells and spell-like abilities that use negative energy, including inflict spells, require the caster to succeed on a Concentration check (DC 15 + the level of the spell). If the check fails, the spell doesn't function but is still lost as a prepared spell or spell slot. If the check succeeds, the spell functions normally."},{"type":"Positive Energy Channeling","kind":"Su","details":"A Large or larger positive energy elemental can channel positive energy as a cleric whose level equals the elemental's Hit Dice. The Will save DC includes a +2 racial bonus."}],"description":"Positive energy elementals are creatures of pure positive energy. They are found primarily on the Positive Energy Plane, but on rare occasions, one slips through a portal or is summoned to the Material Plane. These creatures seem to be able to communicate with others of their kind by changing the intensity of energy in their bodies and altering their shape ever so slightly. Positive energy elementals hate negative energy elementals and always attack them on sight. Aside from that, positive energy elementals rarely engage in combat. If confronted however and forced into battle, the creature responds by pummeling its foes with its powerful fists dealing positive energy to its foe.","ecology":"","habitat_society":""},{"name":"Greater Shedu","cr":10,"xp":9600,"alignment":"LG","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["magic circle against evil"],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":147,"hd":"14d10+70","hdvalue":14,"fort":14,"ref":10,"will":10,"dr":"10/evil","sr":18,"speed":[{"type":"land","speed":40},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"2 hooves +20 (1d6+7)","space":"10 ft.","reach":"5 ft.","spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"astral projection","details":"self only"},{"spell":"clairaudience/ clairvoyance"},{"spell":"detect evil"},{"spell":"detect magic"},{"spell":"detect thoughts"},{"spell":"invisibility","details":"self only"}]},{"frequency":"2/day","spells":[{"spell":"dominate person"},{"spell":"telekinesis"}]}],"spellsprepared_caster_level":10,"spellsprepared_concentration":19,"spellsprepared":[{"spell_level":5,"spell_slots":1,"spells":[{"spell":"breath of life","type":"domain"},{"spell":"greater command"},{"spell":"mass cure light wounds"},{"spell":"righteous might"}]},{"spell_level":4,"spell_slots":1,"spells":[{"spell":"divination"},{"spell":"divine power"},{"spell":"holy smite","type":"domain"},{"spell":"restoration"},{"spell":"spell immunity"}]},{"spell_level":3,"spell_slots":1,"spells":[{"spell":"create food and water"},{"spell":"cure serious wounds","type":"domain"},{"spell":"dispel magic"},{"spell":"prayer"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"bull's strength"},{"spell":"calm emotions"},{"spell":"cure moderate wounds","type":"domain"},{"spell":"eagle's splendor"},{"spell":"remove paralysis"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"bless"},{"spell":"command"},{"spell":"cure light wounds","type":"domain"},{"spell":"divine favor"},{"spell":"endure elements"},{"spell":"remove fear"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"light"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Good, Healing","strength":24,"dexterity":12,"constitution":20,"intelligence":18,"wisdom":18,"charisma":20,"baseatk":14,"cmb":22,"cmd":33,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Diplomacy","value":23},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (planes)","value":22},{"skill":"Fly","value":16},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":22}],"languages":["Celestial","Common","Draconic","telepathy 100 ft."],"sq":[{"type":"ethereal jaunt"}],"environments":["any warm land"],"organizations":["solitary","troupe (greater shedu plus 2-5 shedu)"],"treasure":"standard","description_visual":"This creature has the body of a chestnut-colored horse, large brown-feathered wings, and the head and face of a bearded human. Its long beard and hair is straight-braided.","group":"Shedu","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Magic Circle against Evil","kind":"Su","details":"A greater shedu radiates a continuous magic circle against evil at caster level 14th. This effect can be dispelled, but the greater shedu can resume the magic circle as a free action at will."}],"description":"Greater shedu are the leaders and champions of their race. If encountered with other shedus, they are always in a leadership role, directing their lesser cousins in battle.\n\nA greater shedu's natural weapons, as well as any weapons it wields, are considered good-aligned for the purpose of overcoming damage reduction.\n\nGreater shedu are about 10 ft. long and weigh about 700 pounds.","ecology":"","habitat_society":"","credit":"The Shedu originally appeared in the pre-First Edition book Eldritch Wizardry (© TSR/Wizards of the Coast, 1976) and later in the First Edition Monster Manual (© TSR/Wizards of the Coast, 1977) and is used by permission.  The Greater Shedu originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Greruor Demon","cr":10,"xp":9600,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"ac":27,"ac_touch":15,"ac_flat_footed":24,"ac_mods":"+3 Dex, +12 natural, -1 size, +3 profane","hp":115,"hd":"10d10+60","hdvalue":10,"fort":13,"ref":10,"will":5,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":40}],"melee":"bite +16 (2d6+7) or tongue +16 (grab) or ranseur  +16 (2d6+10/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acid and fire spittle"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"confusion"},{"spell":"deeper darkness"},{"spell":"detect good"},{"spell":"hold person"},{"spell":"shatter"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 9, 1 greruor 35%"}]},{"frequency":"2/day","spells":[{"spell":"blasphemy"}]}],"strength":24,"dexterity":17,"constitution":22,"intelligence":14,"wisdom":14,"charisma":16,"baseatk":10,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":34,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Power Attack"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+23 jump"},{"skill":"Climb","value":20},{"skill":"Escape Artist","value":24},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":19},{"skill":"Stealth","value":12},{"skill":"Survival","value":15}],"languages":["Abyssal","Common","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","pair","troupe (3-6)"],"treasure":"standard","description_visual":"This creature appears as a massive, squat and bloated frog-like creature with arms in place of its forelegs. Two large horns protrude above deep sunken eyes.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid and Fire Spittle","kind":"Ex","details":"Once every 1d4 rounds, a greruor can spit a 30-ft. long line of acid that deals 4d4 points of acid damage. On the greruor's next turn, the acid ignites and the opponent bursts into flames taking 1d6 points of fire damage per round until extinguished. A successful DC 21 Reflex save halves the acid damage and prevents the creature from catching fire. The save DC is Constitution-based."}],"description":"Greruors serve in the infernal armies of several demon lords, particularly Tsathogga. They are strong, powerful, and brutal demons that delight in inflicting pain on others. They are extremely loyal and follow orders without question. Some greater demons, like nalfeshnees and glabrezus, relish the flesh of greruors' legs and often organize hunting parties to track and slay the frog demons. The greruors however are not the weak-minded brutes they appear to be and often win such confrontations using their deadly ranseurs and their large numbers to turn back their opponents.\n\nA greruor appears as a massive, squat, bloated, frog-like demon with arms in place of its forelegs. Its wide, frog-like head has two 3-foot long horns protruding just above its deep, sunken eyes. It moves by hopping on its rear legs. Its arms end in talons which are usually clutched around the greruor's deadly ranseur. Its huge mouth sports razor-sharp teeth of a dull gray color. The greruor stands about 8 ft. tall when on all fours.\n\nIn combat, they stand on their hind legs and attack with their ranseur.\n\nThe greruor's flesh is greenish-brown mottled with red or gray. Its skin constantly oozes and secretes a thick, mucus-like clear slime that is slick to the touch.\n\nGreruors enjoy combat and seek it wherever they can find it. Normally they rely on their natural attacks, spittle, and weapons to fell opponents. If outmatched, they use confusion to disorient opponents, followed closely by shatter. Grabbed opponents are often held in the mouth of one greruor while another stabs the victim with its ranseur.","ecology":"","habitat_society":"","gear":"ranseur"},{"name":"Hag Nymph","cr":10,"xp":9600,"alignment":"CE","size":"Medium","type":"fey","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":21,"ac_flat_footed":19,"ac_mods":"+1 dodge, +5 Dex, +4 natural, +5 profane","hp":75,"hd":"10d6+40","hdvalue":10,"fort":12,"ref":17,"will":-4,"dr":"10/cold iron","resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":30}],"melee":"2 claws +11 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"profane beauty"},{"type":"spells"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"inflict light wounds"}]},{"frequency":"1/day","spells":[{"spell":"baleful polymorph"},{"spell":"summon","details":"level 7, 1d3 shadow demons 50%"}]},{"frequency":"3/day","spells":[{"spell":"inflict serious wounds"}]}],"spellsknown_caster_level":10,"spellsknown_concentration":18,"spellsknown":[{"spell_level":5,"spell_slots":4,"spells":[{"spell":"beast shape III"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"bestow curse"},{"spell":"greater invisibility"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"fly"},{"spell":"haste"},{"spell":"lightning bolt"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"blindness/deafness"},{"spell":"fog cloud"},{"spell":"ghoul touch"},{"spell":"spider climb"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cause fear"},{"spell":"charm person"},{"spell":"chill touch"},{"spell":"disguise self"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"bleed"},{"spell":"daze"},{"spell":"flare"},{"spell":"ghost sound"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"read magic"},{"spell":"touch of fatigue"}]}],"strength":15,"dexterity":21,"constitution":18,"intelligence":16,"wisdom":17,"charisma":21,"baseatk":5,"cmb":4,"cmd":9,"cmd_special":"can't be tripped","feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Diplomacy","value":16},{"skill":"Escape Artist","value":18},{"skill":"Handle Animal","value":11},{"skill":"Intimidate","value":15},{"skill":"Knowledge (nature)","value":12},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":18}],"languages":["Common","Draconic","Giant","Sylvan"],"sq":[{"type":"profane grace"}],"environments":["cold forests","temperate forests"],"organizations":["solitary","coven (3 hag nymphs)"],"treasure":"standard","description_visual":"This hideous, bent crone has sickly green skin, thin dark green hair and hands that end in wicked claws with filthy nails.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Profane Beauty","kind":"Su","details":"This ability affects all humanoids within 30 ft. of a hag nymph. Those who look directly at a hag nymph must succeed on a DC 20 Fortitude save or take 2d4 points of Strength damage. A hag nymph can suppress or resume this ability as a free action. A creature that saves or fails its save cannot be affected by the same hag nymph's profane beauty for one day. The save DC is Charisma-based."},{"type":"Profane Grace","kind":"Su","details":"A hag nymph adds her Charisma modifier as a racial bonus on all her saving throws, and as a profane bonus to her Armor Class. Spells A hag nymph casts spells as a 10th-level sorcerer, and doesn't need any material components."}],"description":"The true origins of the hag nymph are cloaked in secrecy. Tales speak of a band of nymphs that blasphemed their goddess and were punished for dare offending her. Other legends say the hag nymph is the resulting offspring of a demon and nymph. Regardless, these creatures are vile and evil and take great pleasure in tormenting others.\n\nHag nymphs live deep within dark forests in huts composed of mud and timber. These huts are well constructed and littered with the rotting remains of creatures they devour. Hag nymphs relish the taste of humanoid flesh, but sustain themselves on a diet of forest animals when humanoids are scarce. Forays under the cover of darkness into towns on the edge of the forest are not unheard of. In such raids, children are the most likely victims as they are easier to carry away.\n\nHag nymphs stand 6 ft. tall and weigh 150 pounds. Their frames are somewhat emaciated, almost corpse-like in appearance. Their clothes usually carry the bloodstains of previous victims. Hag nymphs live for 150 years.\n\nHag nymphs attack from range bombarding their foes with an array of spells. Slain opponents are dragged to the hag nymph's lair and devoured at her leisure. Occasionally hag nymphs seek to capture rather than kill their opponents. Such opponents are taken prisoner and used as slaves by the hag nymphs, performing manual labor for them or being used as blood sacrifices in dark rituals.","ecology":"","habitat_society":""},{"name":"Hawanar Genie","cr":10,"xp":9600,"alignment":"LN","size":"Large","type":"outsider","subtypes":["air","extraplanar","fire"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+4 Dex, +1 dodge, +7 natural, -1 size","hp":97,"hd":"13d10+26","hdvalue":13,"fort":6,"ref":12,"will":10,"defensive_abilities":["air mastery"],"immunities":["acid","fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"2 slams +20 (2d6+8 plus 1d8 fire) or masterwork  falchion +21 (2d6+12/18-20 plus 1d8 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"heat"},{"type":"holocone","details":"1/10 minutes, 10-50 ft. tall, 1d8+8 plus 1d8 fire damage, DC 27"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"invisibility","details":"self only"},{"spell":"plane shift","details":"willing targets to elemental planes, Astral Plane, or Material Plane only"}]},{"frequency":"1/day","spells":[{"spell":"burning hands"},{"spell":"create food and water"},{"spell":"create wine","details":"as create water, but wine instead"},{"spell":"fireball"},{"spell":"gaseous form"},{"spell":"grant up to 3 wishes","details":"to non-genies only"},{"spell":"invisibility"},{"spell":"major creation","details":"created vegetable matter is permanent"},{"spell":"persistent image"},{"spell":"scorching ray","details":"1 ray only"},{"spell":"wall of fire"},{"spell":"wind walk"}]}],"strength":27,"dexterity":18,"constitution":14,"intelligence":14,"wisdom":15,"charisma":15,"baseatk":13,"cmb":22,"cmd":37,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quicken Spell-like Ability (scorching ray)"},{"feat":"Wind Stance"}],"skills":[{"skill":"Bluff","value":18},{"skill":"Diplomacy","value":18},{"skill":"Fly","value":26},{"skill":"Intimidate","value":18},{"skill":"Knowledge (nobility)","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":12},{"skill":"Spellcraft","value":11}],"languages":["Auran","Celestial","Common","Ignan","telepathy 100 ft."],"environments":["any (Plane of Air)","any (Plane of Fire)"],"organizations":["solitary","pair","company (2-4)","band (6-15)"],"treasure":"standard","description_visual":"This being is twice as tall as a normal human and has reddish skin, no hair, and small fangs. Its lower torso is shrouded in a cyclone of burning embers and flame.","group":"Genie","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against a hawanar."},{"type":"Heat","kind":"Ex","details":"A hawanar's fists are swathed in white-hot fire that deals 1d8 points of extra fire damage whenever it hits in melee, or in each round it maintains a hold when grappling. The hawanar's metallic weapons conduct this heat. The hawanar can suppress or resume this ability as a free action."},{"type":"Holocone","kind":"Su","details":"A hawanar can transform into a vortex of embers and white-hot fire once every 10 minutes. This ability functions identically to the whirlwind ability. In this form, it can move through the air or along a surface at its fly speed. The save DC includes a +3 racial adjustment."}],"description":"Hawanar are the unlikely union of an efreeti noble and a djinni noble.\n\nNeither of the parent races truly accepts the hawanar but the djinn are more tolerant while the efreet usually execute or enslave hawanar offspring on sight, viewing them as something unnatural. A typical hawanar stands 12 ft. tall and weighs about 1,100 pounds.\n\nHawanar society is ruled by a Rajah who is served by a multitude of beys, sheiks, sahibs, and sirdars The hawanar race has no true home and can be found spread throughout the planes (most dwell on the Plane of Air or a pocket plane of air and fire). Those that dwell on the Plane of Fire generally avoid the City of Brass and efreeti patrols due to the disdain the efreet have for them.\n\nHawanar wade into battle in a hail of fire and wind, relying on their spell-like abilities and holocone form to dissuade and vanquish its opponents. If combat goes against it, a hawanar assumes either gaseous form or holocone form and attempts to flee.","ecology":"","habitat_society":"","gear":"masterwork falchion"},{"name":"Impaled Spirit","cr":10,"xp":9600,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense","modifier":"60 ft."}],"auras":["unnatural aura (30 ft.)"],"ac":19,"ac_touch":19,"ac_flat_footed":15,"ac_mods":"+5 deflection, +1 dodge, +3 Dex","hp":126,"hd":"12d8+60 (+12)","hdvalue":12,"fort":9,"ref":7,"will":12,"defensive_abilities":["channel resistance +4","incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"incorporeal spike +12 (1d8 plus impale soul) or incorporeal touch +12 (1d8 plus sickened)","space":"5 ft.","reach":"5 ft. (10 ft. with incorporeal spike)","special_attacks":[{"type":"impale soul"}],"dexterity":16,"intelligence":15,"wisdom":15,"charisma":21,"baseatk":9,"cmb":12,"cmd":31,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":22},{"skill":"Intimidate","value":20},{"skill":"Knowledge (religion)","value":17},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":18}],"languages":["Common"],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"This ghostly spirit's face is twisted in eternal torment. The creature clutches a translucent spear-like pole.","group":"Shattered Soul","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Impale Soul","kind":"Su","details":"An impaled spirit carries an incorporeal version of the spike that caused its death, a 10-foot long spear-like instrument. On a successful melee attack with this spike, the target must succeed on a DC 21 Will save or have its soul impaled on the ghostly implement. A ghostly duplicate of the impaling instrument and its victim now impaled on the spike appear planted in the ground within 5 ft. of the target. A thin silvery cord connects the translucent, impaled creature with its corporeal self. Another thin silvery cord connects the ghostly impalement back to the impaled spirit. This attack deals 1d6 points of Constitution drain initially and 1 point of Constitution drain each round thereafter until the creature dies or is freed. Each round an impaled victim takes Constitution drain, the impaled spirit connected to it gains 5 temporary hit points. An impaled creature cannot move more than 10 ft. from the spot where its soul is impaled, and takes a -2 penalty on all attack rolls, checks, and saves from the pain until freed. An impaled creature can be freed if the ghostly spike holding the victim is destroyed or pulled from the ground. The ghostly spike is AC 20, hp 20, hardness 10. Corporeal creatures cannot pull the spike from the ground but can attack it with magic weapons. Normal weapons have no effect. Ethereal creatures can attack the spike with normal weapons or remove it from the ground with a successful DC 21 Strength check. A heal, holy word, wish, or miracle spell destroys the ghostly spike instantly. The save DC is Charisma-based."},{"type":"Lifesense","kind":"Su","details":"An impaled spirit notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability."},{"type":"Unnatural Aura","kind":"Su","details":"Animals don't willingly approach within 30 ft. of an impaled spirit, unless a master makes a DC 25 Handle Animal, Ride, or wild empathy check."}],"description":"Shattered souls are the ghostly spirits of living beings executed through brutal torture: impalement, disembowelment, or worse. Their souls having not entirely departed the Material Plane, they have risen to seek vengeance on the living, particularly clerics or other divine spellcasters whom they blame for having forsaken them and allowed them to die in such a ghastly manner.\n\nImpaled spirits are the ghostly remains of living beings executed through impalement; a brutally slow and extremely painful form of execution.\n\nImpaled spirits are most often encountered above ground in or near the place of their execution; rarely are they found anywhere else. They are completely oblivious to everything but pain, and seek to inflict as much on a living creature as is inhumanly possible. They hold no memories of their former life, save the pain and suffering they endured at their time of execution.\n\nAm impaled spirit appears as a translucent humanoid floating a few ft. above the ground carrying a 10-foot long ghostly spike or spear. It makes no noise, though it almost seems to be trying to cry out in agony; a silent reminder of the pain endured as the impalement spike pierced its internal organs while it was dying. Its eyes are glossy white.\n\nAn impaled spirit hates all living creatures and attacks any it encounters. Though it can use its incorporeal touch attack, it prefers to attack with its incorporeal spike, attempting to impale its foes. An impaled creature is left to die an agonizing death. The impaled spirit turns its attention to another foe, attempting to repeat the process. Much like other shattered souls, an impaled spirit hates clerics and attacks them first.","ecology":"","habitat_society":""},{"name":"Lurker Wraith","cr":10,"xp":9600,"alignment":"NE","size":"Large","type":"undead","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":112,"hd":"15d8+30 (+15)","hdvalue":15,"fort":7,"ref":8,"will":9,"defensive_abilities":["amorphous","channel resistance +4"],"dr":"10/ silver and piercing or slashing","immunities":["undead traits"],"weaknesses":["sunlight powerlessness","vulnerability to fire"],"speed":[{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"buffet +20 (2d4+15 plus 1d6 Con drain and grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"smother"}],"strength":30,"dexterity":12,"intelligence":6,"wisdom":11,"charisma":14,"baseatk":11,"cmb":22,"cmb_special":"+4 vs. grapple","cmd":33,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Deceitful"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":8},{"skill":"Disguise","value":12,"special":"+20 as curtain, wall hanging or textile"},{"skill":"Fly","value":3},{"skill":"Perception","value":11},{"skill":"Stealth","value":25}],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"A diaphanous, almost translucent curtain blows on a nonexistent breeze towards you. It spreads its folds wide as it approaches as if to envelop you.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Amorphous","kind":"Ex","details":"Lurking wraiths are immune to precision damage (like sneak attacks) and critical hits, and can move through an area as small as one-quarter their space without squeezing or one-eighth their space when squeezing."},{"type":"Constitution Drain","kind":"Su","details":"Creatures hit by a lurker wraith's buffet attack must succeed on a DC 19 Fortitude save or take 1d6 points of Constitution drain. On each such successful attack, the lurker wraith gains 5 temporary hit points. The save DC is Charisma-based."},{"type":"Create Spawn","kind":"Su","details":"A humanoid slain by either a lurker wraith's Constitution drain or smother attack becomes a ghoul in 1d4 rounds. Spawn are not under the command of the lurker wraith (which typically ignores them), but they do instinctively protect their creator. They don't possess any of the abilities they had in life. A humanoid of 4 Hit Dice or more rises as a ghast, not a ghoul."},{"type":"Smother","kind":"Ex","details":"When a lurker wraith grapples a target, it continues its Constitution drain each round (though the victim is still allowed a save each round). In addition it forms an airtight seal around its prey. A grappled target cannot speak or cast spells with verbal components and must hold its breath (see Suffocation)."},{"type":"Sunlight Powerlessness","kind":"Ex","details":"A lurker wraith caught in sunlight cannot attack and is staggered."}],"description":"If there is an undead form of the aberrations known as lurkers, this is surely it. They have a gauzy appearance and resemble some thin cloth, though close inspection reveals they are quite durable and thick with a certain translucence. They often disguise themselves as tapestries or curtains in order to lure the unwary into their smothering embrace. Sometimes they roll themselves up to appear as innocuous bolts of cloth before unfurling and revealing the true horror. They tend to lurk in subterranean areas or within ruins where they avoid rays of direct sunlight.\n\nA lurker wraith is about 10 ft. long by 10 ft. wide and approximately 1/4 inch thick. They weigh less than 50 pounds. Lurker wraiths typically disguise themselves as ordinary textiles and then try to attack prey with surprise by buffeting them and attempting to smother.\n\nThere are often a few stray ghouls lairing near where lurker wraiths dwell - past victims that will come to defend their creator.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Mammoth","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"animal","init":0,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":21,"ac_touch":8,"ac_flat_footed":21,"ac_mods":"+13 natural, -2 size","hp":149,"hd":"13d8+91","hdvalue":13,"fort":14,"ref":8,"will":7,"speed":[{"type":"land","speed":40}],"melee":"gore +19 (2d6+11), slam +19 (1d8+11), 2 stomps +17 (2d6+5)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"trample","details":"1d8+16, DC 27"}],"strength":33,"dexterity":10,"constitution":23,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":9,"cmb":22,"cmb_special":"+2 vs. bull rush","cmd":32,"cmd_special":"+2 vs. bull rush, +4 vs. trip","feats":[{"feat":"Improved Bull Rush"},{"feat":"Iron Will"},{"feat":"Multiattack"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"},{"feat":"Weapon Focus (stomp)"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Perception","value":17}],"environments":["cold forests","cold plains"],"organizations":["solitary","herd (5-20 adults, plus 7-30 calves)"],"treasure":"none","description_visual":"This massive elephant-like creature is covered in long, coarse hair, and its tusks sweep upward in great curves of yellowed ivory.","source":"Tome of Horrors Complete (3pp)","description":"The woolly mammoth is a relative of both the common elephant and the mastodon (see Mastodon elsewhere in this book). Like the mastodon, it is an herbivore and spends its days eating nuts, fruits, berries, and grasses. The typical mammoth consumes nearly 450 pounds of food and 50 gallons of water in a given day. Mammoths travel in herds with the young moving in the center, protected and surrounded by the adults. If danger is present or a threat is imminent, the males move to face the danger, while the females encircle the young. The woolly mammoth generally reproduces in the spring months with young being born about 22 months later. A young woolly mammoth resembles a miniature version of an adult, complete with fur, and under fur. It doesn't yet have the mighty tusks of the mammoth, though the tusks grow in quickly as the young mammoth reaches maturity (around age 12). The mammoth has the same predators as the mastodon; the dire wolf, the smilodon, and man. Man hunts these creatures for the same reason they hunt the mastodon: meat, fur, ivory, or to capture young mammoths to be trained as mounts and beasts of burden. The mammoth is a relative of the elephant and the mastodon though its head is slightly taller than an elephant's and slightly wider than a mastodon's. Its upward curving tusks are longer than those of the mastodon, and its trunk ends in two, small finger-like projections used for grasping branches, fruits, and other such small items. The mammoth stands about 22 ft. tall and is covered in a thick coat of gray, brown, reddish-brown, yellowish-brown, or black fur with a coarse \"under-fur\" beneath it to protect it in harsh climates. Mammoths generally avoid combat unless provoked or the herd is threatened. They have no natural fear of any creature, so don't flee. If the herd is threatened, mammoths fight by goring with their tusks or trampling. Mammoths fight to the death to protect their young. Training a Mammoth A mammoth must be trained before it can bear a rider in combat. To be trained, a mammoth must have a friendly attitude toward the trainer (this can be achieved through a successful Diplomacy check). Training a friendly mammoth requires six weeks of work and a successful Handle Animal check (DC 25). Riding a mammoth requires an exotic saddle. A mammoth can fight while carrying a rider, but the rider cannot also attack unless he or she makes a successful Ride check. Mammoth young are worth 13,000 gp each on the open market. Professional trainers charge up to 2,000 gp to rear or train a mammoth. Carrying Capacity: A light load for a mammoth is up to 4,152 pounds; a medium load, 4,153 to 8,304 pounds; and a heavy load, 8,305 to 12,480 pounds. A mammoth can drag 62,400 pounds.","ecology":"","habitat_society":""},{"name":"Mature Helix Moth","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"vermin","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":23,"ac_touch":10,"ac_flat_footed":21,"ac_mods":"+2 Dex, +13 natural, -2 size","hp":120,"hd":"16d8+48","hdvalue":16,"fort":13,"ref":7,"will":5,"immunities":["vermin traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +15 (2d8+5 plus 1d8 acid plus grab), tail sting +15 (2d6+2 plus poison)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"drone"}],"strength":20,"dexterity":15,"constitution":16,"wisdom":11,"charisma":2,"baseatk":12,"cmb":19,"cmd":27,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"environments":["temperate forests"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This 20-foot long insect has a black abdomen wrapped with spiraling bands of various color and a white underbelly. Three sets of translucent bluish-violet wings extend from its body. A small black sword-like stinger protrudes from the end of its abdomen and its maw clatters with large gray mandibles.","group":"Helix Moth","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Drone","kind":"Ex","details":"The rapid beating of the helix moth's wings creates a droning sound that is audible up to 60 ft. away. This droning clouds the minds of all creatures within 30 ft. that hear it except other helix moths. A successful DC 21 Will save negates the effect. The save DC is Constitution-based. On a failed save, a creature suffers a -4 circumstance penalty to attack rolls, checks and saves for 1 minute. After this time, a new save can be attempted (same DC) if the helix moth's droning can still be heard and the creature is within range. If this save fails, the creature remains affected for another one minute. This continues every minute until a successful save is made or the combat ends. A creature that makes a successful Will save is unaffected by the droning of that helix moth for one day. The droning is a free action so long as the helix moth is airborne. On the ground, it may beat its wings as a move action with the effects as above."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save DC 21; frequency 1/round for 6 rounds; effect 1d4 Strength damage; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"Helix moths are solitary creatures, though on rare occasions a mated pair might be encountered. The lair of an adult helix moth is almost always above ground and usually takes the form of a cave, tunnel, or other such structure.\n\nSuch places are always well-hidden and difficult to reach. When the time comes for a female helix moth to lay her eggs, she hollows out a tunnel in the floor of her lair, forms a large chamber at the end of the tunnel and deposits her eggs in the chamber.\n\nHelix moth larvae lair in a large, 6-foot-diameter ridged tunnels that burrow down into the earth where they eventually open into a large chamber at least 20 square ft. in size. A thick, gray-white slime coats the chamber's floor and walls. Though harmless to living creatures, but generally not pleasant to touch or come in contact with. Occasionally (15% chance) the secretions of the helix moth larva mix with the slime just enough to form a deadly inhalant poison that affects living creatures within the chamber. Those breathing the fumes must make a successful DC 15 Fortitude save or suffer 1d4 points of Constitution damage. A new save must be made every minute. Once a successful save is made, that creature cannot be affected by the fumes again for one day.\n\nTo lay her eggs, the female helix moth uses her acidic secretions and sharpened mandibles to tunnel a hole into the ground and hollow out a large chamber where she lays 2d4 eggs of greenish-gray color.\n\nThe eggs hatch two weeks after fertilization, producing the helix moth larvae, though typically only about 50% of the larva live past the first day.\n\nHelix moths are normally passive creatures except when hunting. During a search for prey, the creature becomes highly aggressive and doesn't hesitate to attack any creature it encounters. A helix moth often journeys up to a mile or more away from its lair in search of prey. Slain prey is carried back to its lair and devoured over a period of several days. The adult helix moth attacks by biting or stinging its prey. Its constant droning affects those that combat it, so the helix moth always tries to stay airborne and within range where it can use this ability while staying out of melee range. Helix moth larvae attack by biting.","ecology":"","habitat_society":""},{"name":"Nabasu Demon","cr":10,"xp":9600,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["paralysis (10-ft., DC 24)"],"ac":30,"ac_touch":12,"ac_flat_footed":29,"ac_mods":"+1 Dex, +1 dodge, +18 natural","hp":175,"hd":"13d10+104","hdvalue":13,"fort":16,"ref":5,"will":11,"dr":"10/cold iron or good","immunities":["death effects","electricity paralysis","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +20 (1d6+7), bite +20 (1d8+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death gaze","details":"10/day, DC 18"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":21,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness","details":"10-ft. radius"},{"spell":"greater teleport","details":"self plus 50 pounds of objects only"}]},{"frequency":"1/day","spells":[{"spell":"regenerate"},{"spell":"summon","details":"level 4, 1 mature nabasu 30% or 2d4 ghouls 60%"}]},{"frequency":"3/day","spells":[{"spell":"enervation"},{"spell":"silence"},{"spell":"vampiric touch"}]}],"strength":25,"dexterity":13,"constitution":26,"intelligence":14,"wisdom":16,"charisma":15,"baseatk":13,"cmb":20,"cmd":32,"feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Escape Artist","value":14},{"skill":"Fly","value":17},{"skill":"Intimidate","value":15},{"skill":"Knowledge (arcana)","value":15},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":31},{"skill":"Stealth","value":17,"special":"+25 in shadowy areas"},{"skill":"Survival","value":16}],"languages":["Abyssal","Common","plus one more","telepathy 100 ft."],"sq":[{"type":"plane shift"}],"environments":["any (Abyss)"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature is tall and thin with large, leathery, scaled, bat-like wings. Its skin is stretched tightly over its bones to the point that its underlying muscles can be seen clearly. Its skin is pale gray. Its hands end in long fingers tipped with razor-sharp talons. Its mouth is filled with tusk-like teeth, dominated by two overgrown tusks that jut upward from its bottom jaw. Its eyes glow with an eerie yellow light.","group":"Demon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Gaze","kind":"Su","details":"Once per day per growth point (minimum 1/day for a demonling, 10/day for a mature nabasu), a nabasu can use its death gaze for a full round. Living creatures within 20 ft. must succeed on a Fortitude save or gain a negative level. A humanoid slain in this manner transforms into a ghoul in 1d4 rounds under the control of the nabasu that created it. The save DC is Charisma-based. If the nabasu dies, any ghouls under its control become free-willed."},{"type":"Plane Shift","kind":"Su","details":"Three times per day a nabasu demonling can shift to the Material Plane, and a mature nabasu can shift between the Abyss and the Material Plane or back. This transports the nabasu and up to six other creatures provided they all link hands with the nabasu. It is otherwise similar to the spell of the same name (CL 10th for the demonling and CL 13th for the mature nabasu)."},{"type":"Feed","kind":"Su","details":"When a nabasu creates a ghoul with its gaze attack, it gains a growth point. It gains a bonus equal to its growth point total on attack rolls, CMB rolls, saving throws, caster level checks, and skill checks. Its maximum hit points increase by 10 for each growth point it gains and its caster level increases by 1. For every 2 growth points, its natural armor bonus, SR, and CR increases by +1. Each time it gains a growth point, the nabasu demonling makes a DC 30 caster level check-success indicates it becomes a mature nabasu. At 10 growth points, a demonling automatically becomes a mature nabasu."},{"type":"Paralysis Aura","kind":"Su","details":"As a free action, once per day, a mature nabasu can release a paralysis arua in a 10-ft. radius. Creatures in the area must succeed on a DC 24 Fort save or be paralyzed for 1d6+4 rounds. Demons are immune to this aura. The save DC is Constitution-based."}],"description":"Nabasu (both plural and singular form) are one of the most malign of demonkind. They derive great pleasure from torturing and killing (albeit slowly) other creatures. Unlike other demons, a nabasu spends a portion of its life on the Material Plane. Those that reach the demonling stage in their growing process travel to the Material Plane where they feed on humanoids in order to continue their maturity. Once a nabasu reaches maturity, it returns to the Abyss to spend the rest of its immortal existence there. A nabasu (demonling or mature) stands 7 ft. tall and weighs about 700 pounds. Nabasu prefer to attack with their claws and bite so they can watch their opponents die a slow and very painful death. A nabasu fights until either it or its opponent is dead, and it never shows mercy to an opponent in battle.","ecology":"","habitat_society":"","credit":"The Nabasu originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Nereid","cr":10,"xp":9600,"alignment":"CN","size":"Medium","type":"fey","subtypes":["water"],"init":9,"senses":[{"type":"low-light vision"}],"auras":["beguiling aura"],"ac":25,"ac_touch":25,"ac_flat_footed":15,"ac_mods":"+5 deflection, +9 Dex, +1 dodge, +0 natural","hp":126,"hd":"12d6+84","hdvalue":12,"fort":11,"ref":17,"will":14,"defensive_abilities":["transparency"],"dr":"10/cold iron","immunities":["cold","poison"],"sr":21,"weaknesses":["shawl"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"touch +15 (poison)","ranged":"spray +15 (poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"drowning kiss"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control water"},{"spell":"suggestion","details":"only against creatures that are currently fascinated by her beguiling aura"}]},{"frequency":"1/day","spells":[{"spell":"summon monster VI","details":"water elementals only"}]}],"strength":11,"dexterity":29,"constitution":24,"intelligence":14,"wisdom":22,"charisma":21,"baseatk":6,"cmb":15,"cmd":37,"feats":[{"feat":"Ability Focus (poison)"},{"feat":"Agile Maneuvers"},{"feat":"Defensive Combat Training"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Escape Artist","value":24},{"skill":"Knowledge (nature)","value":17},{"skill":"Knowledge (nature)","value":17},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":21},{"skill":"Stealth","value":24},{"skill":"Swim","value":23}],"languages":["Aquan","Common","Sylvan"],"sq":[{"type":"change shape","details":"Medium water elemental, elemental body II"},{"type":"unearthly grace"}],"environments":["any aquatic"],"organizations":["solitary","troupe (1 nereid plus 1 giant squid, 1 giant octopus, 1 giant moray eel, or 1 orca)"],"treasure":"standard","description_visual":"This beautiful woman has pearlescent skin and long, dark hair. Her nudity is barely hidden by a diaphanous, wet shawl.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Beguiling Aura","kind":"Su","details":"Any creature sexually attracted to women runs the risk of being beguiled by a nereid if it looks upon her beauty from a distance of 30 ft. or less. If the creature fails a DC 25 Will save, it is immediately fascinated. A nereid may use her suggestion spell-like ability at will against creatures that are fascinated by her beguiling aura. This is a mind-affecting compulsion effect. The save DC is Charisma-based."},{"type":"Drowning Kiss","kind":"Su","details":"A nereid can flood the lungs of a willing, helpless, or fascinated creature by touching it (traditionally by kissing the creature on the lips). If the target cannot breathe water, it cannot hold its breath and immediately begins to drown. On its turn, the target can attempt a DC 23 Fortitude save to cough up this water; otherwise it falls unconscious at 0 hp. On the next round, the target must save again or drop to -1 hit points and be dying; on the third round it must save again or die. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Touch or spray-contact; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d2 Con plus blindness; cure 2 consecutive saves."},{"type":"Shawl","kind":"Ex","details":"A nereid's shawl (hardness 2, hp 6) contains a portion of her life force. If the shawl is ever destroyed, the Nereid takes 1d6 points of Constitution drain per hour until she dies. A nereid can craft a new shawl from water by making a DC 25 Will save, but each attempt takes 1d4 hours to complete. Attempts to destroy or steal a nereid's shawl require the sunder or disarm attempts."},{"type":"Transparency","kind":"Su","details":"When underwater, a nereid's body becomes transparent, effectively rendering her invisible. She can become visible or transparent at will as a free action."},{"type":"Unearthly Grace","kind":"Su","details":"A nereid adds her Charisma bonus as a deflection bonus to her Armor Class and CMD if she wears no armor."}],"description":"The nereid's true form is that of a pool of water (a Medium water elemental). It can assume humanoid form at will (as a free action) and usually takes the form of a very beautiful female with long golden hair, pearly white skin, and green, almond-shaped eyes. Many sailors, seafarers, pirates, and other sea-goers have met their ends at the hands of the nereid. Their natural beauty lures men to their doom, for behind the beauty of the honeyed ones lies certain death for any creature that tries to steal a glance or kiss from the nereid.\n\nNereids shy away from combat and flee at the first sign of conflict if possible. If forced into melee, a nereid uses her poison spray to blind an opponent.","ecology":"","habitat_society":""},{"name":"Piscodaemon","cr":10,"xp":9600,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["aquatic","daemon","evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see invisibility"}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":137,"hd":"11d10+77","hdvalue":11,"fort":14,"ref":7,"will":9,"defensive_abilities":["all-around vision"],"dr":"10/good","immunities":["acid","death effects","disease","flanking","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":21,"speed":[{"type":"land","speed":30},{"type":"swim","speed":50}],"melee":"2 claws +18 (2d6+7/18-20/x3 plus grab and 1d6  bleed), tentacles +16 (1d10+3 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"augmented critical"},{"type":"constrict","details":"2d6+10"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 1d3 hydrodaemons 35%"}]},{"frequency":"3/day","spells":[{"spell":"fly"},{"spell":"stinking cloud"}]}],"strength":25,"dexterity":18,"constitution":24,"intelligence":14,"wisdom":15,"charisma":17,"baseatk":11,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":32,"feats":[{"feat":"Critical Focus"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Sickening Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Escape Artist","value":18},{"skill":"Intimidate","value":17},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":16},{"skill":"Stealth","value":18},{"skill":"Survival","value":16},{"skill":"Swim","value":29}],"languages":["Abyssal","Daemonic","Infernal","telepathy 100 ft."],"sq":[{"type":"amphibious"}],"environments":["any (Gehenna)","any (Hades)","any (Tarterus)"],"organizations":["solitary","team (2-4)","squad (6-10)"],"treasure":"standard","description_visual":"This large creature resembles a bipedal lobster with long, gangly arms that end in powerful pincers. It has a short fish-like tail on its posterior and a centipede-like head with several small tentacles located just beneath its mouth.","group":"Daemon","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Augmented Critical","kind":"Ex","details":"A piscodaemon's claws threaten a critical hit on an 18-20 and inflict x3 damage on a successful critical hit."},{"type":"Poison","kind":"Ex","details":"Tentacles-injury; save Fort DC 22; frequency 1/round for 6 rounds; effect 1d2 Con plus staggered for 1 round; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"Piscodaemons are found throughout the Lower Planes bullying and killing weaker creatures. They are often themselves used as cannon fodder or slaves by the more powerful races of the Lower Planes, particularly the arcanadaemons.\n\nA typical piscodaemon stands about 7 ft. tall and weigh 200 pounds.\n\nA piscodaemon often opens combat with its spell-like abilities, usually using stinking cloud against its foes. It then moves in and slashes and rakes with its claws. If the piscodaemon can grab a foe, it hangs on and constricts.\n\nA piscodaemon's natural weapons, as well as any weapons he wields, are treated as evil-aligned for the purpose of overcoming damage reduction.","ecology":"","habitat_society":"","credit":"The Piscodaemon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Red Jester","cr":10,"xp":9600,"alignment":"CN","size":"Medium","type":"undead","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":14,"ac_flat_footed":20,"ac_mods":"+4 Dex, +10 natural","hp":67,"hd":"15d8","hdvalue":15,"fort":5,"ref":9,"will":11,"defensive_abilities":["channel resistance +4","unassailable mind"],"dr":"10/magic","immunities":["undead traits"],"sr":21,"speed":[{"type":"land","speed":30}],"melee":"+2 light mace of merriment +17 (1d6+4 plus merriment) or 2 slams +13 (1d4+2)","ranged":"jester's deck +15 (see below)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"fear cackle"},{"type":"jester's deck"},{"type":"merriment"}],"strength":15,"dexterity":18,"intelligence":15,"wisdom":14,"charisma":16,"baseatk":11,"cmb":13,"cmd":27,"feats":[{"feat":"Ability Focus (fear cackle)"},{"feat":"Catch Off Guard"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Throw Anything"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Balance","value":17},{"skill":"Intimidate","value":16},{"skill":"Perform (act)","value":16},{"skill":"Perform (comedy)","value":20},{"skill":"Perform (oratory)","value":16},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Sleight of Hand","value":17},{"skill":"Stealth","value":17}],"languages":["Common","Any 2"],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"A horrid walking corpse appears, arrayed in brightly colored clothes, floppy shoes, and a bright red jester's hat complete with jingling bells sewn to the ends of the cap. The rigor mortis seems to have permanently pulled the creature's face into a broad and horrific grin.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Fear Cackle","kind":"Su","details":"A red jester can unleash a fear-inducing cackle as a free action. All creatures within 60 ft. that hear it must make a successful DC 22 Will save or become panicked for 2d4 rounds. Panicked creatures suffer a -2 morale penalty on saves and flee (if possible). A panicked creature has a 50% chance to drop what it's holding. If cornered or unable to flee, a panicked creature cowers. This is a sonic, mind-affecting fear effect. Whether or not the save is successful, an affected creature is immune to that red jester's fear cackle for one day. The save DC is Charisma-based."},{"type":"Jester's Deck","kind":"Su","details":"The red jester uses a deck of playing cards in combat that functions as a deck of many things. Once per round, as a standard action, the red jester can draw a single card and throw it at an opponent to a range of 20 ft. This requires a successful ranged touch attack. If successful, the card takes effect that round and affects the target just as if he had drawn a card from a deck of many things. A red jester can draw the same card more than once. The playing cards only function in the hands of a red jester. To anyone else, they are merely normal playing cards."},{"type":"Merriment","kind":"Su","details":"If a red jester strikes an opponent with its mace, the creature must make a successful DC 20 Will save or fall to the ground laughing for 1d3 rounds. The opponent isn't helpless, but is unable to move or act for the duration. A mace of merriment functions only in the hands of a red jester. In the hands of any other creature it functions as a masterwork light mace."},{"type":"Unassailable Mind","kind":"Ex","details":"The mind of a red jester is a twisted and dangerous place to journey. Being undead, it is immune to all mind-influencing effects and should a creature target the mind of a red jester with such an effect (including psionics, telepathy, or the like), the creature attempting to invade the red jester's mind must make a successful DC Will save or suffer the effects of an insanity spell (caster level 15th). The save DC is Charisma-based."}],"description":"Red jesters are thought to be the undead form of court jesters having been put to death for telling bad jokes, making fun of the local ruler, or dying in an untimely manner (which could be attributed to one or both of the first two). Another legend speaks of the red jesters as being the court jesters of Orcus, Demon Prince of the Undead, sent to the Material Plane to \"entertain\" those the demon prince has chosen to pay special attention to. The actual truth to their origin remains a mystery. While they can be encountered from the coldest to the warmest regions of the world and on any type of terrain, a red jester is generally encountered near civilized areas. Though it is dead (or undead) now, it still delights in entertaining living creatures through its humor and obviously cannot do that if it resides far away in unsettled lands. Some red jesters, in an effort to disguise their undead nature don masks or wear makeup. Red jesters speak Common and at least two other languages and often engage in humor during combat, spilling bad puns and riddles at their opponents. A red jester opens combat using its fear cackle attempting to affect as many opponents as possible. Those that resist its effects are assailed with its magical playing cards and mace. During the entire combat, the red jester talks, laughs, and tells jokes and riddles.","ecology":"","habitat_society":"","gear":"jester's deck; Other Gear +2 light mace of merriment"},{"name":"Scylla","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+2 Dex, +11 natural, -2 size","hp":138,"hd":"12d10+72","hdvalue":12,"fort":14,"ref":10,"will":18,"weaknesses":["water dependency"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":50}],"melee":"6 bites +16 (1d8+6/19-20)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"boil water"},{"type":"heat"},{"type":"scalding blast"}],"strength":23,"dexterity":14,"constitution":23,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":12,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":47,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Critical (bite)"},{"feat":"Intimidating Prowess"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Vital Strike"}],"skills":[{"skill":"Intimidate","value":19},{"skill":"Perception","value":23},{"skill":"Swim","value":19}],"languages":["Aquan","Common"],"environments":["any temperate aquatic","any warm aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This massive sea monster is about 20 ft. long with a rounded lower body, four large fins, a short tail, and six heads, each perched on top of a long snake-like neck.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Boil Water","kind":"Ex","details":"If a scylla uses its heat ability for 3 consecutive rounds and doesn't move more than 5 ft. from its current location, the water surrounding it (in a 10-foot radius and to a depth of 10 ft.) begins to rapidly churn and boil. Creatures caught in the boiling water take 3d6 points of fire damage each round they remain in the area. A successful DC 22 Fortitude save reduces the damage by half. Creatures wearing heavy clothing or medium or heavy armor take a -2 penalty on their saving throw. In addition, those wearing metal armor or coming into contact with very hot metal are affected as if by a heat metal spell. The save DC is Constitution-based. Once the scylla moves from its location or shuts its heat ability off, the boiling water takes 3 rounds to return to its normal temperature (it still deals full damage during its cooling off period). A scylla is immune to its own boil water ability and to the boil water ability of other scyllas."},{"type":"Heat","kind":"Ex","details":"A scylla raises the temperature of its body in order to generate intense heat. It does so as a free action. Creatures attacking a scylla unarmed or with natural weapons take 1d6 points of fire damage each time their attacks hit. In addition, a scylla can use its heat ability to boil the surrounding waters."},{"type":"Scalding Blast","kind":"Ex","details":"A scylla can gulp some of the boiling water surrounding it as a move action. Each head that gulped water can then unleash a line of scalding steam on the scylla's next action to a range of 50 ft. The scylla can target the same or different opponents with each head, if it wishes. Each blast deals 3d6 points of fire damage or half that amount if the target succeeds on a DC 22 Reflex save. The save DC is Constitution-based. This is effective both on the surface and underwater. In any round that a head doesn't gulp water, it can bite."},{"type":"Water Dependency","kind":"Ex","details":"A scylla can survive on land for a number of hours equal to its Constitution modifier (minimum 1 hour). After that, see the Drowning."}],"description":"Scyllas are thought to be related to hydras, though no proof exists connecting the two. They are found in climates from temperate to warm (they don't like the cold) and prefer to lair in natural underwater caves and caverns, only emerging when hungry. A scylla is a predatory creature, existing on a diet of large fish such as shark, octopus or squid, or unlikely swimmers and sailors. Prey is usually devoured in the same spot it is killed; rarely does a scylla return to its lair with prey except when nursing its young. Scyllas are solitary creatures and even during mating season it is rare to actually encounter more than one of these creatures. The mating ritual lasts but a short time with the male swimming away afterwards, never to return to the lair. Young are born about 6 months later and reach maturity in just under a year. Young scyllas are noncombatants and don't possess the heat ability of adult scyllas. A scylla is gray-blue to dark gray in color with a lighter shaded underbelly. Its fins are gray-blue to dark gray. Its eyes are golden or gray and each mouth is lined with triple rows of whitish-gray teeth. Scyllas can grow to a length of 50 ft. Scyllas attack their foes with vicious bites from their multiple heads. When facing more than one opponent, a scylla uses its heat ability to boil the water surrounding it and burn its foes. Scyllas prefer to attack when it is most advantageous, such as surfacing under a foe. If combat goes against a scylla it dives beneath the waves and swims away. A cornered or hungry scylla, or one defending its lair, always fights to the death.","ecology":"","habitat_society":""},{"name":"Sea Giant","cr":10,"xp":9600,"alignment":"CN","size":"Large","type":"humanoid","subtypes":["aquatic","giant"],"init":6,"senses":[{"type":"darvkision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+2 Dex, +12 natural, -1 size","hp":142,"hd":"15d8+75","hdvalue":15,"fort":14,"ref":9,"will":9,"defensive_abilities":["freedom of movement","rock catching"],"speed":[{"type":"land","speed":40},{"type":"swim","speed":30}],"melee":"2 slams +20 (1d8+10)","ranged":"rock +13 (1d8+15)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"crushing pressure"},{"type":"rock throwing","details":"120 ft."}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"}]},{"frequency":"5/day","spells":[{"spell":"control water"}]}],"strength":30,"dexterity":14,"constitution":21,"intelligence":14,"wisdom":14,"charisma":12,"baseatk":11,"cmb":22,"cmb_special":"+2 vs. sunder","cmd":34,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Knowledge [nature])"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":16},{"skill":"Craft (any one)","value":10},{"skill":"Intimidate","value":15},{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":19},{"skill":"Stealth","value":12},{"skill":"Swim","value":23}],"languages":["Aquan","Common","Giant"],"sq":[{"type":"amphibious"}],"environments":["any aquatic"],"organizations":["solitary","gang (2-4)","family (2-4 plus 20% noncombatants plus 1 cleric of 5th-8th level)"],"treasure":"double standard","description_visual":"This huge being has bluish green skin and eyes that reflect light like two silvery moons. Rippling with muscle this creature rises from the depths with a crash of waves on rocks.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Crushing Pressure","kind":"Su","details":"Three times per day as a standard action, a sea giant can increase the water pressure in a 10- foot radius around itself for a number of rounds equal to its Constitution bonus (5 rounds for an average sea giant). Any living creature in the area of increased pressure must succeed on a DC 22 Fortitude save each round it remains in the area or take 1d8 points of damage. The save DC is Constitution-based."}],"description":"Sea giants are the reclusive cousins of storm giants. They are most often found in the deepest depths of the seas where they make their dwelling in the cones of long dead undersea volcanoes. Sea giants have a druid like power over the forces of the seas, and are a living embodiment of its bounty and destructive wrath. Sea giants seldom come into contact with surface dwellers, but have been known on rare occasions to exact bounties from coastal cities to insure the safety of its navies and merchant vessels. Sea giants are most commonly encountered within a few hundred miles of their lair, tending to their domain and battling off incursions of sahaugin, aboleth, krakens and other such destructive forces of the undersea. An adult male sea giant stands 10 ft. tall and weighs about 6,000 pounds. Females are slightly shorter and lighter. Both have sea green skin, dark green or black hair, and silver eyes. Sea giants adorn themselves in loose flowing robes of white, blue, or green. Many wear wreathes of coral in their hair. When battling at the surface of the seas, sea giants hurl rocks at great length against opposing ranged attackers, usually including crews of siege engines. When battling against surface ships their tactic is to disguise themselves by creating rough waters with their control water ability. They then hammer the hull with their mighty fists until it is holed, without ever revealing themselves to the crew. Once holed, they tear the hull apart and drown the crew. When fighting beneath the waves they use their crushing pressure special ability to increase the water pressure around themselves in an effort to destroy interlopers and trespassers.","as_character":[{"description":"Sea giants must possess fourteen levels of humanoid before taking class levels. Sea giants are usually barbarians or clerics. Their chaotic nature lends itself well to the ever-changing seas and oceans, and sea giants like the ocean rarely sit still, spending most of their lives as undersea nomads traveling from place to place. Leaders are usually barbarians and shamans are adepts or clerics with access to two of the following domains: Chaos, Protection, Water. Sea giant characters possess the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+20 Strength, +4 Dexterity, +11 Constitution, +4 Intelligence, +4 Wisdom, +2 Charisma: Sea giants possess the awesome physical strength of the ocean and the mental toughness of creatures accustomed to an ever-changing environment."},{"type":"Large size","value":"Sea giants are Large and have the following adjustments -1 penalty to Armor Class, -1 penalty on attack rolls, -4 penalty on Stealth checks, +1 bonus on CMB/CMD, lifting and carrying limits double those of Medium characters."},{"type":"Space/Reach","value":"10 ft./10 ft."},{"type":"Fast","value":"A sea giant's base speed is 40 ft. Its swim speed is 30 ft."},{"type":"Darkvision","value":"Sea giants can see in the dark up to 60 ft."},{"type":"Low-light vision","value":"Sea giants can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A sea giant begins with fifteen levels of humanoid (giant), which provides it with 15d8 Hit Dice, a base attack bonus of +10, and base saves of Fort +9, Ref +5, and Will +5."},{"type":"Racial Skills","value":"A sea giant's giant levels give it skill points equal to 15 x (2 + Int modifier, minimum 1). Sea giants add Intimidate and Perception to their list of class skills. Sea giants gain a +8 racial bonus to swim checks."},{"type":"Racial Feats","value":"A sea giant's giant levels give it eight feats."},{"type":"AC","value":"Sea giants have +12 natural armor bonus."},{"type":"Natural Weapons","value":"Sea giants can fight with two slams (1d8)."},{"type":"Special Attacks","value":"Crushing pressure (sea above), rock throwing."},{"type":"Special Qualities","value":"Amphibious, rock catching."},{"type":"Spell-Like Abilities","value":"A sea giant is under a constant freedom of movement spell-like ability. A sea giant can cast control water five times per day. He uses his giant levels as hit caster level."},{"type":"Languages","value":"Sea Giants begin play speaking Aquan, Common and Giant. Sea giants with high Intelligence can choose bonus languages from the following list: Auran, Elven, Goblin, Orc."}]}],"ecology":"","habitat_society":""},{"name":"Sepia Snake","cr":10,"xp":9600,"alignment":"N","size":"Huge","type":"magical beast","init":7,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+3 Dex, +10 natural, -2 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":12,"ref":11,"will":5,"dr":"10/magic","speed":[{"type":"land","speed":40},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"bite +17 (1d8+7 plus grab) tail sting +18 (1d8+3 plus  poison)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"cocoon"},{"type":"constrict","details":"1d8+10"},{"type":"gaze"}],"strength":24,"dexterity":16,"constitution":19,"intelligence":4,"wisdom":13,"charisma":19,"baseatk":12,"cmb":21,"cmd":34,"cmd_special":"can't be tripped","feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Improved Poison"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (tail sting)"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":12}],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"Winglessly flying forth, a monstrously sized anaconda-like serpent descends from the sky. Its 30-foot body is nearly two-ft. thick and covered in muddy brown scales with strange patterns and symbols on its dorsal side. Large glowing yellow orbs set in its wide, triangular head emit a haunting glare and arching its tail aggressively, it exposes a vicious-looking barbed stinger.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Cocoon","kind":"Su","details":"Three times per day, a sepia snake can fire a line of webbing to a range of 20 ft. A creature caught in the path can make a successful DC 20 Reflex save to avoid the web. On a failed save, the opponent is wrapped in the snake's webbing. When a foe is completely covered in webbing, it must make a successful DC 20 Fortitude save or be placed in a state of suspended animation as per the sepia snake sigil spell for 1d4+12 days. The save DCs are Constitution-based. In one round, the sepia snake can spit enough webbing to cover one Medium or smaller creature. For each size category larger than Medium, the snake must fire another line of webbing to completely encase an opponent. Victims hit by the webbing, but not completely covered, can break free in one round by making a successful DC 24 Strength check or DC 20 Escape Artist check. Each 5-foot section of webbing has 10 hit points. The check DCs are Constitution-based and the Strength check includes a +4 racial bonus. A foe completely wrapped cannot break the webs and must rely on others to get free."},{"type":"Gaze","kind":"Su","details":"The gaze of a sepia snake crushes the will of an opponent and induces despair if it fails a DC 20 Will save. On a failed save, the opponent suffers a -4 penalty on attack rolls, weapon damage rolls, and ability and skill checks. The save DC is Charisma-based."},{"type":"Poison","kind":"Ex","details":"Tail Sting-Injury; save Fort DC 20; frequency 1/ round for 6 rounds; effect paralysis and 1d2 Dex; cure 1 save. The save DC is Constitution-based."}],"description":"Wizards and other sages well-versed in arcane lore agree that the sepia snake was the inspiration for the spell sepia snake sigil. The similarities between the creature and the spell are simply too great to be coincidental.\n\nThough a sepia snake can be found just about anywhere, it usually makes its lair deep underground in abandoned mines, dungeons, or subterranean caverns. It has been said that to look into the eyes of the sepia snake is to look into one's own doom.\n\nA sepia snake begins combat by using its gaze on what it believes to be its most dangerous opponents so it can safely deal with them later.\n\nIn melee a sepia snake tries to avoid direct combat, and will rely on its Flyby Attack feat to keep it out of danger. A sepia snake can emit a brown, web-like substance from its throat that immobilizes its opponent. Held, cocooned, or otherwise incapacitated foes are poisoned to soften them up for consumption.","ecology":"","habitat_society":""},{"name":"Shadow Dire Bear","cr":10,"xp":9600,"alignment":"CE","size":"Large","type":"undead","subtypes":["incorporeal"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 deflection, +1 Dex, +1 dodge, -1 size","hp":90,"hd":"12d8+24 (+12)","hdvalue":12,"fort":6,"ref":5,"will":9,"defensive_abilities":["channel resistance +2","incorporeal"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"3 incorporeal touches +10 (1d6 Strength damage) or claw +19 (1d6+10 plus grab) and bite +18 (1d8+10)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"}],"strength":31,"dexterity":13,"intelligence":2,"wisdom":12,"charisma":14,"baseatk":9,"cmb":11,"cmb_special":"(incorporeal) or +9 (partially corporeal)","cmd":24,"cmd_special":"(incorporeal) or +8 (partially corporeal)","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"},{"feat":"Weapon Focus (incorporeal touch)"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":11},{"skill":"Stealth","value":4,"special":"+8 dim light"}],"sq":[{"type":"partially corporeal"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A looming shadow like that of a massive bear with claws like sickles rises before you.","group":"Shadow Dire","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any animal reduced to Strength 0 by a shadow dire bear becomes a shadow animal within 1d4 rounds. It isn't under the control of its killer but attacks all living targets immediately."},{"type":"Grab","kind":"Ex","details":"While partially corporeal, a shadow dire bear that hits with a claw attack can then attempt to start a grapple as a free action without provoking an attack of opportunity. The grapple is lost if the shadow dire bear becomes incorporeal again. If the shadow sire bear gains a hold, it automatically deals bite damage each round that the hold is maintained."},{"type":"Partially Corporeal","kind":"Su","details":"As a move action a shadow dire bear can become partially corporeal without provoking attacks of opportunity. It can likewise resume its incorporeal state as a move action without provoking attacks of opportunity. While in its partially corporeal state the shadow dire bear benefits from its natural armor and its Strength bonus for attacks and damage. In this state its attacks have a 20% chance to ignore natural armor, armor, and shields. Likewise, though attacks against it with magic weapons can hit normally, it can ignore damage from attacks with normal weapons from a corporeal source 50% of the time. It doesn't retain any of the other incorporeal traits while in this state."},{"type":"Strength Damage","kind":"Su","details":"The touch of a shadow dire bear while incorporeal deals 1d6 points of Strength damage to a living creature. This is a negative energy effect. A creature dies if this Strength damage equals or exceeds its actual Strength score."}],"description":"A strange incarnation of sentient darkness and feral rage, this is an incorporeal form of a dire bear that resembles its earthly form in all other respects. Its origin lies in the strange result of a shadow's create spawn ability affecting an animal. How such an outcome occurred is anyone's guess, but sages in the lore of undeath have been unable to recreate it since. It is difficult to see in dark or gloomy places but is clearly visible in bright illumination.\n\nLike a dire bear the shadow dire bear is over 12 ft. long, but it is weightless except when partially corporeal when it weighs about 1,000 lb. A shadow dire bear attacks aggressively like its living counterparts with its incorporeal claws and bite alternating this with its grab and tearing claws as it becomes partially corporeal.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Sleeping Willow","cr":10,"xp":9600,"alignment":"NE","size":"Huge","type":"plant","init":1,"senses":[{"type":"low-light vision"},{"type":"tremorsense","modifier":"60 ft."}],"ac":23,"ac_touch":7,"ac_flat_footed":23,"ac_mods":"-1 Dex, +16 natural, -2 size","hp":104,"hd":"11d8+44 (+11)","hdvalue":11,"fort":11,"ref":2,"will":4,"defensive_abilities":["plant traits"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":10}],"melee":"4 slams +15 (2d6+8 19-12/x2 plus grab plus Constitution drain)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"sleep spores"}],"strength":26,"dexterity":8,"constitution":19,"intelligence":7,"wisdom":12,"charisma":11,"baseatk":8,"cmb":18,"cmd":27,"feats":[{"feat":"Cleave"},{"feat":"Improved Critical (slam)"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Stealth","value":0,"special":"+10 in forests"}],"environments":["temperate forests"],"organizations":["solitary","grove (2-5)"],"treasure":"standard","description_visual":"Before you stands a low willow tree with a wide trunk, its bent branches sway solemnly in the breeze.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Constitution Drain","kind":"Su","details":"Any creature grabbed by a sleeping willow must make a successful DC 19 Fortitude save or take1d4 points of Constitution drain each round the hold is maintained as the sleeping willow drains the victim's body fluids. The sleeping willow heals 5 points of damage whenever it drains Constitution, gaining temporary hit points (if bonus hit points exceed the sleeping willows total). At Constitution 0, the creature dies and its body is absorbed by the sleeping willow's roots. The save DC is Constitution-based."},{"type":"Sleep Spores","kind":"Ex","details":"As a standard action, a sleeping willow can eject a cloud of yellowish pollen from its body in a 30-foot spread. Affected creatures must make a successful DC 19 Will save or fall asleep for 10 minutes. There is no HD limit for this sleep effect. The save DC is Constitution-based."}],"description":"Sleeping willows are slow-moving, carnivorous plant creatures with evil dispositions. Most sleeping willows make their home among groves or areas of normal willow trees where they can use their natural appearance to their advantage. Though capable of movement, the sleeping willow only moves at night, so as not to be detected or seen. Once a hunting area becomes depopulated or scarce, the sleeping willow moves on to better hunting grounds where it takes root and repeats the above cycle of waiting, hunting, and moving on to a new location. Sleeping willows don't collect treasure but the treasure from their past victims is often scattered about the base of the tree. Sleeping willows don't mind this, for they know that greedy treasure-seekers will be lured in by this and it makes catching a meal that much easier. A sleeping willow appears as a normal willow tree (and is often mistaken for such) standing 15 or more ft. tall. Some species have been rumored to reach heights in excess of 30 ft. Its trunk is 2 ft. or more in diameter and dark brown in color. From the trunk sprout branches that end in long drooping and graceful twigs. The sleeping willow is crowned with leaves of green or brownish-green. A sleeping willow prefers to attack from ambush when potential prey wanders too close to it. Once prey is in range, the sleeping willow releases its spores and then attacks with its branches, grabbing its prey in its viselike grip. Grappled creatures are drained of their body fluids and absorbed by the tree. A grove of sleeping willows act in concert against multiple opponents, aiding one another when necessary until the opponents are slain or flee.","ecology":"","habitat_society":""}];
